import{_ as d,o as r,c as e,a4 as a}from"./chunks/framework.BMj-uaUw.js";const c=JSON.parse('{"title":"1.3 学习路线与岗位方向","description":"","frontmatter":{},"headers":[{"level":2,"title":"先说一个共性问题","slug":"先说一个共性问题","link":"#先说一个共性问题","children":[]},{"level":2,"title":"三阶段速览","slug":"三阶段速览","link":"#三阶段速览","children":[]},{"level":2,"title":"第二阶段的能力项自查","slug":"第二阶段的能力项自查","link":"#第二阶段的能力项自查","children":[]},{"level":2,"title":"第三阶段的五个方向","slug":"第三阶段的五个方向","link":"#第三阶段的五个方向","children":[{"level":3,"title":"方向一 · 业务开发","slug":"方向一-·-业务开发","link":"#方向一-·-业务开发","children":[]},{"level":3,"title":"方向二 · 跨端开发","slug":"方向二-·-跨端开发","link":"#方向二-·-跨端开发","children":[]},{"level":3,"title":"方向三 · 服务端渲染","slug":"方向三-·-服务端渲染","link":"#方向三-·-服务端渲染","children":[]},{"level":3,"title":"方向四 · 质量与工程","slug":"方向四-·-质量与工程","link":"#方向四-·-质量与工程","children":[]},{"level":3,"title":"方向五 · 可视化","slug":"方向五-·-可视化","link":"#方向五-·-可视化","children":[]}]},{"level":2,"title":"怎么选：三个判断依据","slug":"怎么选-三个判断依据","link":"#怎么选-三个判断依据","children":[]},{"level":2,"title":"一份可执行的自学计划模板","slug":"一份可执行的自学计划模板","link":"#一份可执行的自学计划模板","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"常见坑","slug":"常见坑","link":"#常见坑","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"unit01/03-learning-path.md","filePath":"unit01/03-learning-path.md","lastUpdated":1789307994000}'),o={name:"unit01/03-learning-path.md"};function l(s,t,i,n,h,u){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="_1-3-学习路线与岗位方向" tabindex="-1">1.3 学习路线与岗位方向 <a class="header-anchor" href="#_1-3-学习路线与岗位方向" aria-label="Permalink to &quot;1.3 学习路线与岗位方向&quot;">​</a></h1><h2 id="先说一个共性问题" tabindex="-1">先说一个共性问题 <a class="header-anchor" href="#先说一个共性问题" aria-label="Permalink to &quot;先说一个共性问题&quot;">​</a></h2><p>学前端的人容易陷入一种状态：<strong>什么都看过，什么都做不出来。</strong></p><p>今天刷到&quot;Vue 3 组合式 API 真香&quot;，学两天；明天听说&quot;TypeScript 是刚需&quot;，又去看两天； 后天看到&quot;2026 前端已死&quot;的帖子，心态崩了，躺一周。</p><p>问题不在于不努力，而在于<strong>不知道自己站在路线的哪个位置</strong>，所以每次都在重新开始。</p><p>解决这个问题只需要做一件事：<strong>把自己的位置标出来，然后只看下一站。</strong></p><p>完整的路线在<a href="/frontend-engineering-course/guide/learning-path.html">前端学习路线</a>那一页，这一节聚焦两个更实际的问题： <strong>我离过关还差什么</strong>，以及<strong>过关之后往哪走</strong>。</p><h2 id="三阶段速览" tabindex="-1">三阶段速览 <a class="header-anchor" href="#三阶段速览" aria-label="Permalink to &quot;三阶段速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>关键词</th><th>对应</th></tr></thead><tbody><tr><td>一 · 打地基</td><td>能用原生技术做出会动的页面</td><td>HTML、CSS、JS、DOM、调试</td><td>先修课程</td></tr><tr><td>二 · 上装备</td><td>能用现代工程化方式做项目</td><td>工具链、框架、组件、架构、交付</td><td><strong>本课程 48 学时</strong></td></tr><tr><td>三 · 定方向</td><td>能按岗位方向深入</td><td>领域深度 + 工程能力</td><td>后续课程与自学</td></tr></tbody></table><p>判断自己在哪一阶段，用三个问题：</p><ol><li>能不看资料写出一个带表单校验、能请求数据的页面吗？→ 过了第一阶段。</li><li>能在干净电脑上让你的项目 15 分钟内跑起来吗？→ 过了第二阶段的一半。</li><li>能说清你的项目为什么这么分层、这么拆组件吗？→ 过了第二阶段。</li></ol><h2 id="第二阶段的能力项自查" tabindex="-1">第二阶段的能力项自查 <a class="header-anchor" href="#第二阶段的能力项自查" aria-label="Permalink to &quot;第二阶段的能力项自查&quot;">​</a></h2><p>这一阶段就是本课程的内容。下面这张表可以直接当自查表用，<strong>每一项的判断标准都是&quot;能独立做出来&quot;</strong>：</p><table tabindex="0"><thead><tr><th>能力项</th><th>过关标准</th><th>对应单元</th><th>自检题</th></tr></thead><tbody><tr><td>工程化认知</td><td>能说清工程化解决的六类问题</td><td>1</td><td>不看笔记说出那六类</td></tr><tr><td>工具链</td><td>能独立初始化工程并配好规范</td><td>2 - 3</td><td>从空目录到跑起来，全程不查教程</td></tr><tr><td>框架核心</td><td>会用组合式 API 写出响应式交互</td><td>4 - 6</td><td>手写一个带搜索、分页、排序的表格</td></tr><tr><td>组件化</td><td>能按职责拆组件、设计接口</td><td>7 - 8</td><td>把一个 400 行的页面拆成合理结构</td></tr><tr><td>应用架构</td><td>能用路由与状态组织多页面应用</td><td>9 - 10</td><td>实现强制刷新后登录态不丢</td></tr><tr><td>交付能力</td><td>能打包、部署、写交接文档</td><td>11 - 12</td><td>别人按你的 README 能跑起来</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">自查时对自己诚实</p><p>最常见的自我误判是&quot;这个我看过，算会&quot;。看过的标准太低 —— 教程看一遍、视频刷一遍， 顶多算&quot;知道有这个东西&quot;。</p><p><strong>真正的标准是：关掉所有资料，能不能从空文件开始写出来。</strong> 写不出来就如实打叉，回对应单元重做。诚实一点，反而省时间。</p></div><h2 id="第三阶段的五个方向" tabindex="-1">第三阶段的五个方向 <a class="header-anchor" href="#第三阶段的五个方向" aria-label="Permalink to &quot;第三阶段的五个方向&quot;">​</a></h2><p>第二阶段结束后，你会面临选择。下面五个方向是当前就业市场上比较清晰的出口， 每个方向都写清了&quot;日常做什么、要补什么、拿什么练手&quot;。</p><h3 id="方向一-·-业务开发" tabindex="-1">方向一 · 业务开发 <a class="header-anchor" href="#方向一-·-业务开发" aria-label="Permalink to &quot;方向一 · 业务开发&quot;">​</a></h3><p><strong>最常见，岗位最多。</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>日常做什么</td><td>做后台管理系统、企业信息化系统、运营配置平台。大量表格、表单、权限、流程</td></tr><tr><td>核心技能</td><td>复杂表单与表格、组件库二次封装、权限体系（菜单级 / 按钮级）、性能优化、TypeScript</td></tr><tr><td>要补什么</td><td>TypeScript（重点）、Element Plus / Ant Design Vue 的深度使用、表单引擎</td></tr><tr><td>练手项目</td><td>把本课程的校园活动平台加上&quot;数据字典管理&quot;&quot;操作日志&quot;&quot;角色权限配置&quot;三个模块</td></tr><tr><td>典型出口</td><td>各类企业的前端团队、外包与项目制公司</td></tr></tbody></table><p><strong>为什么它岗位最多</strong>：因为绝大多数公司的前端工作就是&quot;把内部流程搬到网页上&quot;。 这个方向不需要炫技，需要的是<strong>稳、准、能处理边界情况</strong>。</p><h3 id="方向二-·-跨端开发" tabindex="-1">方向二 · 跨端开发 <a class="header-anchor" href="#方向二-·-跨端开发" aria-label="Permalink to &quot;方向二 · 跨端开发&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>日常做什么</td><td>用一套代码出小程序、H5、App 三个端</td></tr><tr><td>核心技能</td><td>uni-app 或 Taro、小程序规范、多端适配与条件编译、原生能力调用（支付、扫码、定位）</td></tr><tr><td>要补什么</td><td>小程序的生命周期与分包机制、平台差异处理、真机调试</td></tr><tr><td>练手项目</td><td>把本课程项目里的两个页面移植到 uni-app，跑通浏览器与小程序模拟器</td></tr><tr><td>典型出口</td><td>小程序服务商、零售与本地生活类业务、外包公司</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">课程里的入口</p><p><a href="/frontend-engineering-course/unit12/">单元 12</a> 结束后给了一个课外拓展：用 uni-app 把“活动列表”与“活动报名详情” 两个页面移植到移动端，复用同一套接口。不占课内学时，是想走这个方向的同学的起点。</p></div><p><strong>这个方向的坑</strong>：不要一上来就学&quot;多端适配技巧&quot;。先把一个端做扎实（比如小程序）， 再考虑多端 —— 否则三端都有问题，排查起来会崩溃。</p><h3 id="方向三-·-服务端渲染" tabindex="-1">方向三 · 服务端渲染 <a class="header-anchor" href="#方向三-·-服务端渲染" aria-label="Permalink to &quot;方向三 · 服务端渲染&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>日常做什么</td><td>做官网、内容型站点、电商前台这类<strong>需要被搜索引擎收录</strong>的页面</td></tr><tr><td>核心技能</td><td>Nuxt（Vue 生态）或 Next.js、SSR 与预渲染、SEO 基础、部署到 Node 服务</td></tr><tr><td>要补什么</td><td>HTTP 缓存、Node 服务部署、首屏性能指标（LCP、FCP）</td></tr><tr><td>练手项目</td><td>用 Nuxt 做一个校园活动对外展示站，要求首屏内容在 HTML 源码里能看到</td></tr><tr><td>典型出口</td><td>内容与电商类公司、需要 SEO 的业务团队</td></tr></tbody></table><p><strong>这个方向的门槛</strong>：它要求你同时对前端和后端部署有一定了解。 不像业务开发那样纯前端，但因此也更稀缺。</p><details class="details custom-block"><summary>用一句话说清 SSR 解决什么问题</summary><p>普通单页应用的 HTML 源码里只有一个空 <code>&lt;div id=&quot;app&quot;&gt;&lt;/div&gt;</code>，搜索引擎抓到的就是&quot;这个页面是空的&quot;。 SSR 是在服务器上先把页面渲染成完整 HTML 再返回，<strong>搜索引擎和用户拿到的是有内容的页面</strong>。</p><p>代价是：多了一层 Node 服务，部署变复杂了，页面里有状态的代码要注意&quot;在服务端能不能跑&quot;。</p></details><h3 id="方向四-·-质量与工程" tabindex="-1">方向四 · 质量与工程 <a class="header-anchor" href="#方向四-·-质量与工程" aria-label="Permalink to &quot;方向四 · 质量与工程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>日常做什么</td><td>写测试、搭 CI 流水线、做监控与埋点、维护脚手架与构建配置</td></tr><tr><td>核心技能</td><td>Vitest 单元测试、Playwright 端到端测试、CI 流水线、构建性能优化、监控体系</td></tr><tr><td>要补什么</td><td>测试设计思路（测什么、不测什么）、Node 脚本编写、CI 平台（云效 Flow、GitHub Actions）</td></tr><tr><td>练手项目</td><td>给本课程项目补上单元测试（从时段冲突检测这类纯函数入手）与一条自动构建流水线</td></tr><tr><td>典型出口</td><td>前端基础设施团队、测试开发岗、中大型公司的工程效团队</td></tr></tbody></table><p><strong>这个方向最容易被忽略，但需求真实存在</strong>：团队越大，越需要有人负责&quot;让大家写得顺&quot;。</p><h3 id="方向五-·-可视化" tabindex="-1">方向五 · 可视化 <a class="header-anchor" href="#方向五-·-可视化" aria-label="Permalink to &quot;方向五 · 可视化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>日常做什么</td><td>做数据看板、大屏、地图可视化、图表交互</td></tr><tr><td>核心技能</td><td>ECharts、Canvas 与 SVG、WebGL 基础、大屏适配、性能优化（大量数据点）</td></tr><tr><td>要补什么</td><td>图形学基础、数据可视化设计原则、Canvas 图层与动画</td></tr><tr><td>练手项目</td><td>给本课程的数据看板做一次升级：加一个可下钻的图表和一个地图分布图</td></tr><tr><td>典型出口</td><td>数据可视化公司、BI 团队、政企大屏项目</td></tr></tbody></table><p><strong>这个方向的特点</strong>：入门容易（ECharts 会配就能出图），做深很难（数据量大时的性能、 自定义图形、交互设计）。</p><h2 id="怎么选-三个判断依据" tabindex="-1">怎么选：三个判断依据 <a class="header-anchor" href="#怎么选-三个判断依据" aria-label="Permalink to &quot;怎么选：三个判断依据&quot;">​</a></h2><p>不要靠&quot;哪个听起来高级&quot;来选。看这三条：</p><table tabindex="0"><thead><tr><th>依据</th><th>怎么判断</th></tr></thead><tbody><tr><td><strong>你做过什么还算顺手</strong></td><td>回顾过去半年，哪个任务你做的时候不觉得痛苦 —— 那就是信号</td></tr><tr><td><strong>目标岗位的招聘要求</strong></td><td>打开招聘网站，搜你想去的岗位，看 20 条 JD 都提到什么，出现频率最高的就是必修项</td></tr><tr><td><strong>你愿意为它花额外时间</strong></td><td>有些方向需要课外投入（比如可视化要学图形学）。想清楚你愿不愿意</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个更务实的建议</p><p><strong>先选业务开发作为保底，再发展一个方向作为特色。</strong></p><p>原因：业务开发岗位最多，容错率最高；而任何特色方向都需要一定的业务开发能力做基础 —— 可视化也得会写表格，跨端也得会做表单。</p><p>本课程的训练目标就是让你达到业务开发的入门水平，特色方向是加分项。</p></div><h2 id="一份可执行的自学计划模板" tabindex="-1">一份可执行的自学计划模板 <a class="header-anchor" href="#一份可执行的自学计划模板" aria-label="Permalink to &quot;一份可执行的自学计划模板&quot;">​</a></h2><p>选好方向后，别写&quot;我要学 TypeScript&quot;，这没法执行也没有终点。用这个模板：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td>目标</td><td>具体到能做出什么</td><td>用 TypeScript 重写本项目的 API 层与两个 store</td></tr><tr><td>交付物</td><td>能拿出来看的东西</td><td>一个提交记录，类型覆盖率达标</td></tr><tr><td>验收标准</td><td>怎么算做完</td><td><code>pnpm build</code> 通过且无 <code>any</code> 类型</td></tr><tr><td>时间盒</td><td>限定时间，避免无限拖延</td><td>三周，每周 6 小时</td></tr><tr><td>卡住时找谁</td><td>不要一个人硬扛</td><td>先查官方文档，再问同学 / 老师</td></tr></tbody></table><p><strong>关键差别在于&quot;交付物&quot;和&quot;验收标准&quot;。</strong> 没有这两栏的计划，多半会变成&quot;看了一堆教程，什么也没留下&quot;。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学前端最大的坑不是不努力，而是<strong>不知道自己站在哪</strong>。</li><li>第二阶段的能力项自查表可以直接当清单用，<strong>标准是&quot;能独立做出来&quot;</strong>。</li><li>五个方向：业务开发、跨端、服务端渲染、质量与工程、可视化。</li><li>选方向的三个依据：做过什么顺手、招聘要求、愿不愿意多花时间。</li><li><strong>先保业务开发，再选一个特色方向。</strong></li><li>自学计划必须写清交付物与验收标准，否则等于没写。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><details class="details custom-block"><summary>坑 1：同时学三个方向</summary><p>结果通常是三个都停在&quot;入门教程看完&quot;的水平。<strong>一个方向做到能讲清楚，比三个方向都听过一遍更值钱。</strong></p></details><details class="details custom-block"><summary>坑 2：把&quot;换框架&quot;当成&quot;换方向&quot;</summary><p>从 Vue 换到 React，不叫换方向，叫换工具。<strong>方向是按解决的问题分的，不是按框架分的。</strong> 今天用 Vue 做后台管理，明天用 React 做后台管理，这是同一个方向。</p></details><details class="details custom-block"><summary>坑 3：只是收集资料，不动手</summary><p>存了 200 GB 的视频和电子书，一个项目都没做完。这类&quot;学习&quot;的产出是零。</p><p><strong>检验方法很简单：把你过去三个月的学习成果列出来，有没有能演示的东西？</strong> 没有就是有问题。</p></details><details class="details custom-block"><summary>坑 4：看到&quot;前端已死&quot;就焦虑</summary><p>每隔几年就会有一轮这样的说法。事实是：<strong>做简单页面的需求确实在减少， 但能做工程化交付的前端一直缺人。</strong></p><p>这门课教的东西 —— 工程化、组件设计、异常处理、交付能力 —— 恰恰是 AI 工具最难替代的部分： 它们需要对项目的整体理解和取舍判断，不是生成一段代码能解决的。</p></details><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><details class="details custom-block"><summary>练习 1：写出自己的位置与差距</summary><p>用一页纸回答这四个问题：</p><ol><li>我在三阶段的哪一站？</li><li>第二阶段自查表里，哪些我打了勾、哪些没打？<strong>列出具体没过的项。</strong></li><li>这门课结束后，我想往哪个方向深入？给出两条理由。</li><li>这个方向目前我缺什么？</li></ol><p><strong>参考思路</strong>：第 2 问是关键。写&quot;框架核心基本会了&quot;没有意义，要写&quot;计算属性会用， 但 <code>watch</code> 的 <code>deep</code> 和 <code>immediate</code> 说不清楚&quot;，这样才知道下一步做什么。</p></details><details class="details custom-block"><summary>练习 2：拆解 20 条招聘要求</summary><p>到招聘网站搜索&quot;前端开发工程师&quot;，挑 20 条校招或初级岗位的 JD（不要挑高级岗位）， 把所有技能关键词统计出现次数，做成一张表。</p><p><strong>参考思路</strong>：统计完你会发现几个规律 —— Vue / React 至少会一个、Git 是硬要求、 TypeScript 出现频率很高、有项目经验的要求几乎 100%。</p><p><strong>这张表就是你后续学习优先级的依据</strong>：出现次数高的先学。</p></details><details class="details custom-block"><summary>练习 3：写一份三周自学计划</summary><p>按本节模板，给你选定的方向写一份三周计划。要求：必须有<strong>交付物</strong>和<strong>验收标准</strong>。</p><p><strong>参考思路</strong>：计划要小到能做完。比如&quot;三周学会 TypeScript&quot;不行， &quot;三周把项目的 API 层与两个 store 改成 TypeScript，<code>pnpm build</code> 通过，无 <code>any</code>&quot;才行。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit01/02-modern-project.html">1.2 一个现代前端工程长什么样</a> · 下一节：<a href="/frontend-engineering-course/unit01/04-environment.html">1.4 开发环境搭建与自检</a></p>',56)])])}const g=d(o,[["render",l]]);export{c as __pageData,g as default};
